M(salv, r"""
public static java.util.ArrayList plan(@IC@[] cs, String[] ids, long[] q, long[] left) {
  java.util.ArrayList out = new java.util.ArrayList();
  java.util.HashSet used = new java.util.HashSet();
  int[] order = new int[] { 2, 1, 3 };
  for (int n = 0; n < ids.length; n++) {
    long need = q[n];
    int mx = @PKG@.WdCodec.maxStack(ids[n]);
    for (int o = 0; o < order.length && need > 0L; o++) {
      int i = order[o];
      if (i >= cs.length || cs[i] == null) continue;
      int cap = cs[i].getCapacity();
      for (int s = 0; s < cap && need > 0L; s++) {
        if (used.contains(i + ":" + s)) continue;
        @IS@ x = @PKG@.WdInv.at(cs, i, s);
        if (x == null || !ids[n].equals(x.getItemId())) continue;
        org.bson.BsonDocument md = x.getMetadata();
        if (md != null && !md.isEmpty()) continue;
        int room = mx - x.getQuantity();
        if (room <= 0) continue;
        int add = need < (long) room ? (int) need : room;
        out.add(new Object[] { Integer.valueOf(i), Integer.valueOf(s), ids[n], Integer.valueOf(x.getQuantity() + add), Integer.valueOf(add) });
        used.add(i + ":" + s);
        need = need - (long) add;
      }
    }
    for (int o = 0; o < order.length && need > 0L; o++) {
      int i = order[o];
      if (i >= cs.length || cs[i] == null) continue;
      int cap = cs[i].getCapacity();
      for (int s = 0; s < cap && need > 0L; s++) {
        if (used.contains(i + ":" + s) || @PKG@.WdInv.at(cs, i, s) != null) continue;
        int add = need < (long) mx ? (int) need : mx;
        out.add(new Object[] { Integer.valueOf(i), Integer.valueOf(s), ids[n], Integer.valueOf(add), Integer.valueOf(add) });
        used.add(i + ":" + s);
        need = need - (long) add;
      }
    }
    left[n] = need;
  }
  return out;
}""")
M(salv, r"""
public static int stacks(String[] ids, long[] left) {
  int n = 0;
  for (int i = 0; i < ids.length; i++) {
    if (left[i] <= 0L) continue;
    long mx = (long) @PKG@.WdCodec.maxStack(ids[i]);
    n = n + (int) ((left[i] + mx - 1L) / mx);
  }
  return n;
}""")
M(salv, r"""
public static void rollback(@IC@[] cs, java.util.ArrayList done) {
  for (int i = done.size() - 1; i >= 0; i--) {
    Object[] o = (Object[]) done.get(i);
    int sec = ((Integer) o[0]).intValue();
    short sl = (short) ((Integer) o[1]).intValue();
    @IS@ old = (@IS@) o[2];
    if (old == null) @PKG@.WdInv.takeOff(cs[sec], sl); else @PKG@.WdInv.put(cs[sec], sl, old);
  }
}""")
