        class GearSalvStandIn(object):
            """SkyyGear 0.3.17's gear:fn:salvage contract: {UUID, id, metadata, mode} -> {why, String[] ids, Long[] qty, key}"""
            @JOverride
            def apply(self, a):
                iid, md, mode = str(a[1]), a[2], str(a[3])
                gst["calls"].append(mode)
                d_ = g_doc(md)
